USE planning_tool;
DROP TABLE IF EXISTS vessel_product_mapping;
-- columns map to original Excel headers:
--   division = DIVISION
--   product_name = PRODUCT NAME
--   equipment_id = EQUIPMENT ID
--   equipment_capacity_in_kgs = EQUIPMENT CAPACITY (IN KGS)
--   min_batch_size_in_kgs = MIN BATCH SIZE (IN KGS)
--   max_batch_size_in_kgs = MAX BATCH SIZE (IN KGS)
--   packing_size = PACKING SIZE
--   equipment_cleaning_time_if_any_in_hrs = EQUIPMENT CLEANING TIME, IF ANY (IN HRS)
--   rm_charging_time_actual_in_hrs = RM CHARGING TIME ACTUAL (IN HRS)
--   rm_charging_time_actual_in_hrs_extra_15_time = RM CHARGING TIME ACTUAL (IN HRS)(EXTRA 15% TIME)
--   mixing_time_in_hrs = MIXING TIME (IN HRS)
--   heating_time_if_any_in_hrs = HEATING TIME, IF ANY (IN HRS)
--   cooling_time_if_any_in_hrs = COOLING TIME, IF ANY (IN HRS)
--   qc_analysis_time_in_hrs = QC ANALYSIS TIME (IN HRS)
--   packing_time_in_hrs = PACKING TIME (IN HRS)
--   cycle_time_in_hrs = CYCLE TIME (IN HRS)
--   cycle_time_in_hrs_2 = CYCLE TIME (IN HRS)
--   previous_cycle_time_in_hrs = PREVIOUS CYCLE TIME (IN HRS)
--   remarks = REMARKS
--   rm_charging_and_processing_time_in_hrs = RM Charging  and processing time
--   sl_no = Sl No
--   category = CATEGORY
--   equipment_capacity_l = Equipment Capacity (L)
--   rm_charging_hrs = RM Charging Hrs
--   mixing_hrs = Mixing Hrs
--   analysis_hrs = Analysis Hrs
--   correction_hrs = Correction Hrs
--   observation_hrs = Observation  HRS
--   reanalysis_hrs = Reanalysis Hrs
--   labeling_packing_hrs = Labeling & Packing Hrs
--   equipment_cleaning_time_in_hrs = EQUIPMENT CLEANING TIME  (IN HRS)
--   cycle_time_equipment_with_cleaning_in_hrs = CYCLE TIME EQUIPMENT WITH CLEANING(IN HRS)
--   cycle_time_equipment_with_out_cleaning_time_in_hrs = CYCLE TIME EQUIPMENT WITH OUT CLEANING TIME(IN HRS)
CREATE TABLE vessel_product_mapping (
  id BIGINT AUTO_INCREMENT PRIMARY KEY,
  organization VARCHAR(64) NOT NULL,
  product_type VARCHAR(32) NULL,
  source_file VARCHAR(128) NULL,
  `division` VARCHAR(255) NULL,
  `product_name` VARCHAR(255) NULL,
  `equipment_id` VARCHAR(255) NULL,
  `equipment_capacity_in_kgs` VARCHAR(255) NULL,
  `min_batch_size_in_kgs` VARCHAR(255) NULL,
  `max_batch_size_in_kgs` VARCHAR(255) NULL,
  `packing_size` VARCHAR(255) NULL,
  `equipment_cleaning_time_if_any_in_hrs` VARCHAR(255) NULL,
  `rm_charging_time_actual_in_hrs` VARCHAR(255) NULL,
  `rm_charging_time_actual_in_hrs_extra_15_time` VARCHAR(255) NULL,
  `mixing_time_in_hrs` VARCHAR(255) NULL,
  `heating_time_if_any_in_hrs` VARCHAR(255) NULL,
  `cooling_time_if_any_in_hrs` VARCHAR(255) NULL,
  `qc_analysis_time_in_hrs` VARCHAR(255) NULL,
  `packing_time_in_hrs` VARCHAR(255) NULL,
  `cycle_time_in_hrs` VARCHAR(255) NULL,
  `cycle_time_in_hrs_2` VARCHAR(255) NULL,
  `previous_cycle_time_in_hrs` VARCHAR(255) NULL,
  `remarks` VARCHAR(255) NULL,
  `rm_charging_and_processing_time_in_hrs` VARCHAR(255) NULL,
  `sl_no` VARCHAR(255) NULL,
  `category` VARCHAR(255) NULL,
  `equipment_capacity_l` VARCHAR(255) NULL,
  `rm_charging_hrs` VARCHAR(255) NULL,
  `mixing_hrs` VARCHAR(255) NULL,
  `analysis_hrs` VARCHAR(255) NULL,
  `correction_hrs` VARCHAR(255) NULL,
  `observation_hrs` VARCHAR(255) NULL,
  `reanalysis_hrs` VARCHAR(255) NULL,
  `labeling_packing_hrs` VARCHAR(255) NULL,
  `equipment_cleaning_time_in_hrs` VARCHAR(255) NULL,
  `cycle_time_equipment_with_cleaning_in_hrs` VARCHAR(255) NULL,
  `cycle_time_equipment_with_out_cleaning_time_in_hrs` VARCHAR(255) NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

